//! Original Rust JavaScript-runtime foundation. Not yet a complete ECMAScript implementation.
mod lexer;mod parser;use std::collections::{HashMap,HashSet};pub use lexer::{LexError,Token,TokenKind};use parser::{Expr,ParseError,Parser,Stmt};
#[derive(Clone,Debug,PartialEq)]pub enum Value{Number(f64),String(String),Boolean(bool),Null,Undefined}
impl Value{fn truthy(&self)->bool{match self{Self::Boolean(v)=>*v,Self::Null|Self::Undefined=>false,Self::Number(n)=>*n!=0.0&&!n.is_nan(),Self::String(s)=>!s.is_empty()}}fn display(&self)->String{match self{Self::Number(n)if n.fract()==0.0=>format!("{n:.0}"),Self::Number(n)=>n.to_string(),Self::String(s)=>s.clone(),Self::Boolean(v)=>v.to_string(),Self::Null=>"null".into(),Self::Undefined=>"undefined".into()}}}
#[derive(Debug,PartialEq)]pub enum EngineError{Lex(LexError),Parse(ParseError),Type(String),Reference(String),Syntax(String)}
impl std::fmt::Display for EngineError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::Lex(e)=>write!(f,"lex error: {e}"),Self::Parse(e)=>write!(f,"parse error: {e}"),Self::Type(s)=>write!(f,"type error: {s}"),Self::Reference(s)=>write!(f,"reference error: {s}"),Self::Syntax(s)=>write!(f,"syntax error: {s}")}}}impl std::error::Error for EngineError{}impl From<LexError> for EngineError{fn from(e:LexError)->Self{Self::Lex(e)}}impl From<ParseError> for EngineError{fn from(e:ParseError)->Self{Self::Parse(e)}}
#[derive(Default)]pub struct Runtime{globals:HashMap<String,Value>,constants:HashSet<String>,output:Vec<String>}
impl Runtime{
pub fn new()->Self{Self::default()}pub fn execute(&mut self,s:&str)->Result<Value,EngineError>{let p=Parser::new(lexer::tokenize(s)?).parse_program()?;self.execute_list(p)}pub fn take_output(&mut self)->Vec<String>{std::mem::take(&mut self.output)}pub fn get_global(&self,n:&str)->Option<&Value>{self.globals.get(n)}
fn execute_list(&mut self,p:Vec<Stmt>)->Result<Value,EngineError>{let mut last=Value::Undefined;for s in p{last=self.execute_statement(s)?}Ok(last)}
fn execute_statement(&mut self,s:Stmt)->Result<Value,EngineError>{match s{Stmt::Expression(e)=>self.eval(e),Stmt::Declaration{name,value,constant}=>{if self.globals.contains_key(&name){return Err(EngineError::Syntax(format!("'{name}' has already been declared")))}let v=self.eval(value)?;self.globals.insert(name.clone(),v.clone());if constant{self.constants.insert(name);}Ok(v)},Stmt::Block(b)=>self.execute_list(b),Stmt::If{condition,then_branch,else_branch}=>if self.eval(condition)?.truthy(){self.execute_list(then_branch)}else if let Some(b)=else_branch{self.execute_list(b)}else{Ok(Value::Undefined)},Stmt::While{condition,body}=>{let mut last=Value::Undefined;while self.eval(condition.clone())?.truthy(){last=self.execute_list(body.clone())?}Ok(last)}}}
fn eval(&mut self,e:Expr)->Result<Value,EngineError>{match e{Expr::Literal(v)=>Ok(v),Expr::Identifier(n)=>self.globals.get(&n).cloned().ok_or_else(||EngineError::Reference(format!("{n} is not defined"))),Expr::Assign{name,value}=>{if !self.globals.contains_key(&name){return Err(EngineError::Reference(format!("{name} is not defined")))}if self.constants.contains(&name){return Err(EngineError::Type(format!("assignment to constant variable '{name}'")))}let v=self.eval(*value)?;self.globals.insert(name,v.clone());Ok(v)},Expr::Unary{op,value}=>{let v=self.eval(*value)?;match op.as_str(){"!"=>Ok(Value::Boolean(!v.truthy())),"+"=>self.number(v).map(Value::Number),"-"=>self.number(v).map(|n|Value::Number(-n)),_=>Err(EngineError::Syntax(format!("unsupported unary operator {op}")))}},Expr::Binary{op,left,right}=>{let a=self.eval(*left)?;if op=="&&"&&!a.truthy(){return Ok(a)}if op=="||"&&a.truthy(){return Ok(a)}let b=self.eval(*right)?;self.binary(&op,a,b)}}}
fn number(&self,v:Value)->Result<f64,EngineError>{match v{Value::Number(n)=>Ok(n),Value::Boolean(b)=>Ok(if b{1.0}else{0.0}),Value::Null=>Ok(0.0),Value::String(s)if s.trim().is_empty()=>Ok(0.0),Value::String(s)=>s.trim().parse().map_err(|_|EngineError::Type("cannot convert string to number".into())),Value::Undefined=>Ok(f64::NAN)}}
fn binary(&self,op:&str,a:Value,b:Value)->Result<Value,EngineError>{if op=="+"&&(matches!(a,Value::String(_))||matches!(b,Value::String(_))){return Ok(Value::String(format!("{}{}",a.display(),b.display())))}if op=="==="||op=="!=="{let e=equal(&a,&b);return Ok(Value::Boolean(if op=="==="{e}else{!e}))}if op=="=="||op=="!="{let e=loose(&a,&b,self)?;return Ok(Value::Boolean(if op=="=="{e}else{!e}))}if let(Value::String(x),Value::String(y))=(&a,&b){if matches!(op,"<"|"<="|">"|">="){return Ok(Value::Boolean(match op{"<"=>x<y,"<="=>x<=y,">"=>x>y,">="=>x>=y,_=>false}))}}if op=="&&"{return Ok(if a.truthy(){b}else{a})}if op=="||"{return Ok(if a.truthy(){a}else{b})}let x=self.number(a)?;let y=self.number(b)?;Ok(match op{"+"=>Value::Number(x+y),"-"=>Value::Number(x-y),"*"=>Value::Number(x*y),"/"=>Value::Number(x/y),"%"=>Value::Number(x%y),"**"=>Value::Number(x.powf(y)),"<"=>Value::Boolean(x<y),"<="=>Value::Boolean(x<=y),">"=>Value::Boolean(x>y),">="=>Value::Boolean(x>=y),_=>return Err(EngineError::Syntax(format!("unsupported binary operator {op}")))})}}
fn equal(a:&Value,b:&Value)->bool{match(a,b){(Value::Number(x),Value::Number(y))=>x==y,(Value::String(x),Value::String(y))=>x==y,(Value::Boolean(x),Value::Boolean(y))=>x==y,(Value::Null,Value::Null)|(Value::Undefined,Value::Undefined)=>true,_=>false}}
fn loose(a:&Value,b:&Value,r:&Runtime)->Result<bool,EngineError>{if equal(a,b){return Ok(true)}match(a,b){(Value::Null,Value::Undefined)|(Value::Undefined,Value::Null)=>Ok(true),(Value::Number(_),Value::String(_))|(Value::String(_),Value::Number(_))|(Value::Boolean(_),_)|(_,Value::Boolean(_))=>Ok(r.number(a.clone())?==r.number(b.clone())?),_=>Ok(false)}}
#[cfg(test)]mod tests{use super::*;#[test]fn precedence(){assert_eq!(Runtime::new().execute("1+2*(3+4)").unwrap(),Value::Number(15.0))}#[test]fn assign(){let mut r=Runtime::new();r.execute("let x=4; x=x+1;").unwrap();assert_eq!(r.execute("x").unwrap(),Value::Number(5.0))}#[test]fn const_guard(){let mut r=Runtime::new();r.execute("const x=4").unwrap();assert!(matches!(r.execute("x=5"),Err(EngineError::Type(_))))}#[test]fn if_else(){let mut r=Runtime::new();r.execute("let x=1; if(x<2){x=8;}else{x=9;}").unwrap();assert_eq!(r.execute("x").unwrap(),Value::Number(8.0))}#[test]fn while_loop(){let mut r=Runtime::new();r.execute("let i=0; while(i<4){i=i+1;}").unwrap();assert_eq!(r.execute("i").unwrap(),Value::Number(4.0))}#[test]fn equality(){let mut r=Runtime::new();assert_eq!(r.execute("1==='1'").unwrap(),Value::Boolean(false));assert_eq!(r.execute("1=='1'").unwrap(),Value::Boolean(true))}}